<tr><td>Samiksha Adhikari, U.P. Public Service Commission</td><td>3</td></tr>
<tr><td>Samiksha Adhikari, Board of Revenue, U.P.</td><td>6</td></tr>
<tr><td>Samiksha Adhikari (Account), U.P. Secretariat</td><td>31</td></tr>
<tr><td>Sahayak Samiksha Adhikari, U.P. Secretariat</td><td>261</td></tr>
<tr><td>Sahayak Samiksha Adhikari, U.P. Public Service Commission</td><td>21</td></tr>
<tr><td>Sahayak Samiksha Adhikari, Board of Revenue, U.P.</td><td>2</td></tr>
